catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
   if (isLoading || newValue == '') {
      return;
   }

   // GlideAjax-Objekt erstellen und Parameter hinzufügen
   var ga = new GlideAjax('UpdateVariableQuestion');
   ga.addParam('sysparm_name', 'updateQuestionText'); // Name der aufzurufenden Funktion im Script Include
   ga.addParam('sysparm_sys_id', 'c62f43663bb19e1013b9202a85e45a05');
   ga.addParam('sysparm_variable_name', 'x_sigh_a_a_portal_attribute_1');
   ga.addParam('sysparm_new_question_text', 'Memory');

   // Asynchrone Anfrage senden und Antwort verarbeiten
   ga.getXMLAnswer(function(response) {
      var answer = response;
      if (answer == 'success') {
         // Erfolgreiche Aktualisierung
         console.log('Variable question text updated successfully');

         // Client-seitige Aktualisierung des Labels
         var variableName = 'x_sigh_a_a_portal_attribute_1';
         var newLabel = 'Memmory';
         g_form.setLabelOf(variableName, newLabel);
      } else {
         // Fehlgeschlagene Aktualisierung
         console.log('Failed to update variable question text');
      }
   });
}
